package com.hostelcare.controller;
import com.hostelcare.dto.ApiDtos.*; import com.hostelcare.service.AuthService; import com.hostelcare.repository.UserRepository; import com.hostelcare.entity.User; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.security.Principal; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;private final UserRepository users;public AuthController(AuthService a,UserRepository u){auth=a;users=u;} @PostMapping("/register") public AuthResponse register(@Valid @RequestBody RegisterRequest r){return auth.register(r);} @PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){return auth.login(r);} @GetMapping("/me") public Map<String,Object> me(Principal p){User u=users.findByEmail(p.getName()).orElseThrow();return ViewMapper.user(u);} }
